BEGIN
    IF OLD.state='FULFILLED' AND (NOT (BINARY NEW.state <=> BINARY OLD.state) OR NOT (BINARY NEW.reason_code <=> BINARY OLD.reason_code)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Original performed completion is permanent';
    END IF;
END

BEGIN
    IF OLD.state='PERFORMED' AND (NOT (BINARY NEW.state <=> BINARY OLD.state) OR NOT (BINARY NEW.current_execution_no <=> BINARY OLD.current_execution_no) OR NEW.attempt_no<>OLD.attempt_no) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Original performed completion is permanent';
    END IF;
END

